#[derive(Default, PartialEq, Debug, Clone)]
pub struct DirectoryList {
    pub slots: Vec<ListSlot>,
}

impl DirectoryList {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsDirectoryList<'a>> {
        use crate::types::generated::fs_generated::DirectoryListBuilder as FbsDirectoryListBuilder;

        let mut slots_offsets = Vec::with_capacity(self.slots.len());
        for val in self.slots.iter() {
            let offset = val.serialize_to(builder);
            slots_offsets.push(offset);
        }
        let slots_offset = builder.create_vector(&slots_offsets);

        let mut bldr = FbsDirectoryListBuilder::new(builder);
        bldr.add_slots(slots_offset);
        bldr.finish()
    }
}

impl From<FbsDirectoryList<'_>> for DirectoryList {
    fn from(fbs: FbsDirectoryList<'_>) -> Self {
        let mut slots = Vec::new();
        for elem in fbs.slots() {
            slots.push(elem.into());
        }

        Self { slots }
    }
}

impl DirectoryList {
    pub fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    pub fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let fbs = flatbuffers::size_prefixed_root::<FbsDirectoryList>(bytes)?;
        Ok(Self::from(fbs))
    }
}

#[derive(Default, PartialEq, Debug, Clone)]
pub struct ListSlot {
    pub attributes: Option<Vec<Attr>>,
    pub entry: ListEntry,
    pub id: ObjectId,
    pub last_modified_by: Option<B2cId>,
    pub name: String,
    pub size_: u64,
    pub time: u64,
    pub user_permissions: u32,
}

impl ListSlot {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsListSlot<'a>> {
        use crate::types::generated::fs_generated::ListSlotBuilder as FbsListSlotBuilder;

        let attributes_offset = self.attributes.as_ref().map(|v| {
            let mut attributes_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                attributes_offsets.push(offset);
            }
            let attributes_offset = builder.create_vector(&attributes_offsets);
            attributes_offset
        });
        let (entry_offset, entry_ty) = self.entry.serialize_to(builder);
        let id_offset = self.id.serialize_to(builder);
        let last_modified_by_offset = self
            .last_modified_by
            .as_ref()
            .map(|o| o.serialize_to(builder));
        let name_offset = builder.create_string(&self.name);

        let mut bldr = FbsListSlotBuilder::new(builder);
        if let Some(offset) = attributes_offset {
            bldr.add_attributes(offset);
        }
        bldr.add_entry(entry_offset);
        bldr.add_entry_type(entry_ty);
        bldr.add_id(id_offset);
        if let Some(offset) = last_modified_by_offset {
            bldr.add_last_modified_by(offset);
        }
        bldr.add_name(name_offset);
        bldr.add_size_(self.size_);
        bldr.add_time(self.time);
        bldr.add_user_permissions(self.user_permissions);
        bldr.finish()
    }
}

impl From<FbsListSlot<'_>> for ListSlot {
    fn from(fbs: FbsListSlot<'_>) -> Self {
        let attributes = if let Some(val) = fbs.attributes() {
            let mut attributes = Vec::new();
            for elem in val {
                attributes.push(elem.into());
            }

            Some(attributes)
        } else {
            None
        };

        let entry = match fbs.entry_type() {
            FbsListEntry::ListFile => {
                ListEntry::ListFile(ListFile::from(fbs.entry_as_list_file().unwrap()))
            }
            FbsListEntry::ListDirectory => ListEntry::ListDirectory(ListDirectory::from(
                fbs.entry_as_list_directory().unwrap(),
            )),
            FbsListEntry::ListObject => {
                ListEntry::ListObject(ListObject::from(fbs.entry_as_list_object().unwrap()))
            }
            FbsListEntry::TopLevelDirectory => ListEntry::TopLevelDirectory(
                TopLevelDirectory::from(fbs.entry_as_top_level_directory().unwrap()),
            ),
            _ => unreachable!(),
        };

        let id = ObjectId::from(fbs.id());
        let last_modified_by = fbs.last_modified_by().map(B2cId::from);
        let name = fbs.name().to_owned();
        let size_ = fbs.size_();
        let time = fbs.time();
        let user_permissions = fbs.user_permissions();
        Self {
            attributes,
            entry,
            id,
            last_modified_by,
            name,
            size_,
            time,
            user_permissions,
        }
    }
}

impl ListSlot {
    pub fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    pub fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let fbs = flatbuffers::size_prefixed_root::<FbsListSlot>(bytes)?;
        Ok(Self::from(fbs))
    }
}

#[derive(Default, PartialEq, Debug, Clone)]
pub struct MoveRequest {
    pub dest_name: Option<String>,
    pub dest_root: Option<ObjectId>,
    pub entry: ObjectId,
    pub overwrite: bool,
}

impl MoveRequest {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsMoveRequest<'a>> {
        use crate::types::generated::fs_generated::MoveRequestBuilder as FbsMoveRequestBuilder;

        let dest_name_offset = self.dest_name.as_ref().map(|s| builder.create_string(s));
        let dest_root_offset = self.dest_root.as_ref().map(|o| o.serialize_to(builder));
        let entry_offset = self.entry.serialize_to(builder);

        let mut bldr = FbsMoveRequestBuilder::new(builder);
        if let Some(offset) = dest_name_offset {
            bldr.add_dest_name(offset);
        }
        if let Some(offset) = dest_root_offset {
            bldr.add_dest_root(offset);
        }
        bldr.add_entry(entry_offset);
        bldr.add_overwrite(self.overwrite);
        bldr.finish()
    }
}

impl From<FbsMoveRequest<'_>> for MoveRequest {
    fn from(fbs: FbsMoveRequest<'_>) -> Self {
        let dest_name = fbs.dest_name().map(ToOwned::to_owned);
        let dest_root = fbs.dest_root().map(ObjectId::from);
        let entry = ObjectId::from(fbs.entry());
        let overwrite = fbs.overwrite();
        Self {
            dest_name,
            dest_root,
            entry,
            overwrite,
        }
    }
}

impl MoveRequest {
    pub fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    pub fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let fbs = flatbuffers::size_prefixed_root::<FbsMoveRequest>(bytes)?;
        Ok(Self::from(fbs))
    }
}

